function poolFalso(resultados) {
  const consultas = [];
  return {
    consultas,
    async query(texto, valores) {
      consultas.push({ texto, valores });
      return resultados.shift() || { rows: [], rowCount: 0 };
    },
    async end() {}
  };
}

test('inicializa en PostgreSQL una tabla con codigo unico y datos del link', async function () {
  const pool = poolFalso([]);
  const repositorio = crearRepositorioPostgres(pool);

  await repositorio.inicializar();

  assert.match(pool.consultas[0].texto, /CREATE TABLE IF NOT EXISTS links/i);
  assert.match(pool.consultas[0].texto, /codigo\s+VARCHAR\(3\)\s+PRIMARY KEY/i);
  assert.match(pool.consultas[0].texto, /clicks\s+INTEGER\s+NOT NULL/i);
});

test('crea un link sin pisar otro codigo y avisa si hubo colision', async function () {
  const pool = poolFalso([
    { rows: [{ codigo: 'a3k' }], rowCount: 1 },
    { rows: [], rowCount: 0 }
  ]);
  const repositorio = crearRepositorioPostgres(pool);
  const link = {
    codigo: 'a3k',
    url: 'https://ejemplo.com',
    clicks: 0,
    creado: '2026-03-02T14:11:09.000Z'
  };

  assert.equal(await repositorio.crear(link), true);
  assert.equal(await repositorio.crear(link), false);
  assert.match(pool.consultas[0].texto, /ON CONFLICT \(codigo\) DO NOTHING/i);
  assert.deepEqual(pool.consultas[0].valores, ['a3k', 'https://ejemplo.com', 0, link.creado]);
});

