test('POST /api/links reintenta el codigo si el generado ya existe', async function (t) {
  const ctx = await iniciarServerDeTest([
    { codigo: 'aaa', url: 'https://ya-existia.com', clicks: 0, creado: '2026-01-01T00:00:00.000Z' }
  ]);

  // primer intento de generarCodigo cae en "aaa" (colision), el segundo en "sss" (libre)
  const secuencia = [0, 0, 0, 0.5, 0.5, 0.5];
  t.mock.method(Math, 'random', function () {
    return secuencia.shift();
  });

  try {
    const res = await fetch(ctx.baseUrl + '/api/links', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: 'https://ejemplo.com/nueva' })
    });
    const body = await res.json();

    assert.equal(body.codigo, 'sss');

    const links = ctx.leerDB();
    assert.equal(links.length, 2);
    assert.equal(links.find(function (l) { return l.codigo === 'aaa'; }).url, 'https://ya-existia.com');
    assert.equal(links.find(function (l) { return l.codigo === 'sss'; }).url, 'https://ejemplo.com/nueva');
  } finally {
    await ctx.cerrar();
  }
});

const CARACTERES = 'abcdefghijklmnopqrstuvwxyz0123456789';

// genera un codigo corto de 3 caracteres
function generarCodigo() {
  let codigo = '';
  for (let i = 0; i < 3; i++) {
    codigo += CARACTERES[Math.floor(Math.random() * CARACTERES.length)];
  }
  return codigo;
}

module.exports = { generarCodigo };

